WITH op AS (SELECT id FROM operators WHERE slug='bingo-auctions'), a AS (SELECT * FROM operator_audit_log, op WHERE operator_audit_log.operator_id=op.id AND created_at>=now()-interval '84 days')
SELECT
(SELECT json_agg(x) FROM (SELECT action_type, count(*) n FROM a GROUP BY 1 ORDER BY 2 DESC LIMIT 25) x) actions,
(SELECT json_build_object('refund_rows', count(*), 'missing', count(*) FILTER (WHERE reason_note ~* 'missing|cant find|can.t find|not found|lost'), 'damaged', count(*) FILTER (WHERE reason_note ~* 'damag|broken|crack|defect|not work'), 'wrong_desc', count(*) FILTER (WHERE reason_note ~* 'wrong|descri|not as|incomplete|parts'), 'customer_cancel', count(*) FILTER (WHERE reason_note ~* 'changed mind|cancel|dont want|don.t want|accident|mistake'), 'dup', count(*) FILTER (WHERE reason_note ~* 'dup'), 'null_note', count(*) FILTER (WHERE reason_note IS NULL OR reason_note='')) FROM a WHERE action_type ~* 'refund') refund_notes,
(SELECT json_agg(x) FROM (SELECT coalesce(after_state->>'reason', after_state->>'refund_reason', 'n/a') r, count(*) n FROM a WHERE action_type ~* 'refund' GROUP BY 1 ORDER BY 2 DESC LIMIT 12) x) refund_reasons,
(SELECT json_agg(x) FROM (SELECT w.name, count(DISTINCT au.id) auctions, count(l.id) FILTER (WHERE l.winner_bidder_id IS NOT NULL) sold, sum(l.current_bid_cents) FILTER (WHERE l.winner_bidder_id IS NOT NULL) hammer_c FROM lots l JOIN auctions au ON au.id=l.auction_id JOIN warehouses w ON w.id=au.warehouse_id, op WHERE l.operator_id=op.id AND l.closed_at>=now()-interval '84 days' GROUP BY 1) x) by_wh,
(SELECT json_build_object('ref_codes', count(*) FILTER (WHERE referral_code IS NOT NULL), 'referred', count(*) FILTER (WHERE referred_by IS NOT NULL), 'tax_exempt', count(*) FILTER (WHERE tax_exempt), 'resale_cert', count(*) FILTER (WHERE resale_cert_status IS NOT NULL), 'new84', count(*) FILTER (WHERE created_at>=now()-interval '84 days'), 'marketing_ok', count(*) FILTER (WHERE marketing_emails_enabled), 'push', count(*) FILTER (WHERE expo_push_token IS NOT NULL)) FROM bidders WHERE deleted_at IS NULL) bidder_flags,
(SELECT json_agg(x) FROM (SELECT width_bucket(n,1,60,6) b, count(*) buyers, sum(spend) spend_c FROM (SELECT bidder_id, count(*) n, sum(subtotal_cents) spend FROM invoices i, op WHERE i.operator_id=op.id AND created_at>=now()-interval '84 days' AND status::text <> 'canceled' GROUP BY 1) z GROUP BY 1 ORDER BY 1) x) buyer_buckets,
(SELECT json_build_object('top20_share', (SELECT sum(s) FROM (SELECT sum(subtotal_cents) s FROM invoices i, op WHERE i.operator_id=op.id AND created_at>=now()-interval '84 days' GROUP BY bidder_id ORDER BY 1 DESC LIMIT 20) t)::numeric / nullif((SELECT sum(subtotal_cents) FROM invoices i, op WHERE i.operator_id=op.id AND created_at>=now()-interval '84 days'),0))) conc
